// A simple local server for the skeleton: no internet, no outside packages.
// NASA's ISS research software rules ask for installers that need no internet, say simple
// server implementations work best, and ask that data be kept in plain files with no personal
// information in file names. This file needs only Node.js.
// It serves the page, and keeps the events (readings and reviews) in app/data, one plain file
// per person, named by the person's id. Nothing leaves this computer.
// Run: node serve.mjs   then open http://127.0.0.1:8080/
// Code generated by Claude (Anthropic), an AI system.
import { createServer } from 'node:http';
import { appendFile, mkdir, readdir, readFile, stat } from 'node:fs/promises';
import { extname, join, normalize, resolve, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(fileURLToPath(new URL('.', import.meta.url)));
// DATA_DIR lets the automatic checks use a throwaway folder instead of the real data.
const DATA = process.env.DATA_DIR ? resolve(process.env.DATA_DIR) : join(ROOT, 'data');
const HOST = process.env.HOST || '127.0.0.1';
const PORT = Number(process.env.PORT) || 8080;
const TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.woff2': 'font/woff2',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.txt': 'text/plain; charset=utf-8',
  '.md': 'text/markdown; charset=utf-8',
  '.wasm': 'application/wasm', // the camera models' runtime (vendor/mediapipe)
  '.task': 'application/octet-stream', // the camera models themselves
};
// Developer folders and the data folder are not served as files.
const HIDDEN = new Set(['tests', 'tools', 'node_modules', '.git', 'data']);
const PERSON_ID = /^[a-z0-9][a-z0-9-]{0,31}$/;
const MAX_BODY = 64 * 1024;

function reply(res, code, body, type = 'application/json; charset=utf-8') {
  const data = body === undefined ? '' : (typeof body === 'string' ? body : JSON.stringify(body));
  res.writeHead(code, { 'Content-Type': type, 'Content-Length': Buffer.byteLength(data), 'Cache-Control': 'no-store', 'X-Content-Type-Options': 'nosniff' });
  res.end(data);
}

// An event must look exactly like what the page sends; anything else is refused.
function validEvent(e) {
  if (!e || typeof e !== 'object' || Array.isArray(e)) return false;
  if (e.v !== 1 || !['reading', 'review', 'report'].includes(e.kind)) return false;
  if (typeof e.person !== 'string' || !PERSON_ID.test(e.person)) return false;
  if (typeof e.time !== 'string' || !Number.isFinite(new Date(e.time).getTime())) return false;
  if (e.state !== undefined) {
    if (!e.state || typeof e.state !== 'object') return false;
    for (const k of ['aiWorks', 'doctorOnBoard', 'linkToEarth']) if (typeof e.state[k] !== 'boolean') return false;
  }
  // A message to a doctor from the front side: to whom, and the text.
  if (e.kind === 'report') {
    const r = e.report;
    if (!r || typeof r !== 'object') return false;
    if (r.to !== 'doctor-onboard' && r.to !== 'doctor-earth') return false;
    if (typeof r.text !== 'string' || r.text.length > 4000) return false;
  }
  if (e.kind === 'reading') {
    const r = e.reading;
    if (!r || typeof r !== 'object') return false;
    if (typeof r.source !== 'string' || r.source.length > 64) return false;
    if (typeof r.indicator !== 'string' || r.indicator.length > 32) return false;
  }
  return true;
}

async function readEvents() {
  let files = [];
  try {
    files = (await readdir(DATA)).filter((f) => f.endsWith('.jsonl'));
  } catch {
    return [];
  }
  const events = [];
  for (const f of files) {
    const text = await readFile(join(DATA, f), 'utf8');
    for (const line of text.split('\n')) {
      if (!line.trim()) continue;
      try {
        const e = JSON.parse(line);
        if (validEvent(e)) events.push(e);
      } catch {
        // a damaged line is skipped, the rest is kept
      }
    }
  }
  return events.sort((a, b) => new Date(a.time) - new Date(b.time));
}

async function readBody(req) {
  const chunks = [];
  let size = 0;
  for await (const chunk of req) {
    size += chunk.length;
    if (size > MAX_BODY) throw new Error('too big');
    chunks.push(chunk);
  }
  return Buffer.concat(chunks).toString('utf8');
}

async function api(req, res) {
  if (req.method === 'GET') {
    reply(res, 200, await readEvents());
    return;
  }
  if (req.method === 'POST') {
    let event;
    try {
      event = JSON.parse(await readBody(req));
    } catch {
      reply(res, 400, { error: 'not readable' });
      return;
    }
    if (!validEvent(event)) {
      reply(res, 400, { error: 'not a valid event' });
      return;
    }
    await mkdir(DATA, { recursive: true });
    await appendFile(join(DATA, `${event.person}.jsonl`), `${JSON.stringify(event)}\n`, 'utf8');
    reply(res, 204);
    return;
  }
  res.writeHead(405, { Allow: 'GET, POST' });
  res.end();
}

const server = createServer(async (req, res) => {
  try {
    let path = decodeURIComponent(new URL(req.url, 'http://localhost').pathname);
    if (path === '/api/events') {
      await api(req, res);
      return;
    }
    if (req.method !== 'GET' && req.method !== 'HEAD') {
      res.writeHead(405, { Allow: 'GET, HEAD' });
      res.end();
      return;
    }
    if (path.endsWith('/')) path += 'index.html';
    const file = resolve(ROOT, `.${normalize(path)}`);
    if (!file.startsWith(ROOT + sep)) {
      res.writeHead(403);
      res.end();
      return;
    }
    if (HIDDEN.has(file.slice(ROOT.length + 1).split(sep)[0])) {
      res.writeHead(404);
      res.end();
      return;
    }
    const info = await stat(file);
    if (!info.isFile()) throw new Error('not a file');
    const body = await readFile(file);
    res.writeHead(200, {
      'Content-Type': TYPES[extname(file).toLowerCase()] || 'application/octet-stream',
      'Content-Length': body.length,
      // Third-party files never change, so the browser may keep them; our own files are always fresh.
      'Cache-Control': path.startsWith('/vendor/') ? 'public, max-age=86400' : 'no-store',
      'X-Content-Type-Options': 'nosniff',
    });
    res.end(req.method === 'HEAD' ? undefined : body);
  } catch {
    if (!res.headersSent) res.writeHead(404);
    res.end();
  }
});

server.listen(PORT, HOST, () => {
  console.log(`Skeleton running at http://${HOST}:${PORT}/ (no internet needed). Data: ${DATA}. Stop with Ctrl+C.`);
});
